codeExercises.solution:
import math

def p_collision(N, k):
    """Probabilità esatta che tra k valori uniformi su N ci sia almeno una coincidenza."""
    p_distinct = 1.0
    for i in range(k):
        p_distinct *= (N - i) / N
    return 1 - p_distinct

def p_approx(N, k):
    return 1 - math.exp(-k * (k - 1) / (2 * N))

def k_half(N):
    k = 1
    while p_collision(N, k) < 0.5:
        k += 1
    return k

for k in (10, 23, 30, 50):
    print(f"k={k:2d}  esatta={p_collision(365, k):.4f}  approx={p_approx(365, k):.4f}")
print("k per il 50% con N=365:", k_half(365))
for n in (16, 20, 24):
    N = 2 ** n
    print(f"n={n}: k_50%={k_half(N)}  sqrt(2 ln2 N)={math.sqrt(2*math.log(2)*N):.1f}  2^(n/2)={2**(n//2)}")

