codeExercises.solution:
import hashlib

def H(data: bytes) -> int:
    return int.from_bytes(hashlib.sha256(data).digest(), "big")

def solve_puzzle(r: bytes, d: int):
    """Trova il primo nonce x tale che SHA-256(r||x) abbia almeno d bit iniziali a zero."""
    target = 1 << (256 - d)          # S = {h : h < target}
    x = 0
    while True:
        if H(r + x.to_bytes(8, "big")) < target:
            return x, x + 1          # nonce, tentativi
        x += 1

def verify(r: bytes, x: int, d: int) -> bool:
    return H(r + x.to_bytes(8, "big")) < (1 << (256 - d))

RUNS = {8: 400, 12: 200, 16: 60}
for d in (8, 12, 16):
    tent = [solve_puzzle(f"blocco-{i}".encode(), d)[1] for i in range(RUNS[d])]
    print(f"d={d:2d} ({RUNS[d]} puzzle): media tentativi={sum(tent)/len(tent):8.1f}   atteso 2^d={2**d}")

x, n = solve_puzzle(b"blocco-0", 16)
print("soluzione d=16:", x, "tentativi:", n, "verifica:", verify(b"blocco-0", x, 16))
print("hash:", hashlib.sha256(b"blocco-0" + x.to_bytes(8, "big")).hexdigest())
